'use strict';
/**
 * Parity with the former Python toolchain (generate.py, checker.py, linter.py + lxml).
 *
 * golden.json holds what that toolchain printed / wrote on 31 variants of the registries (valid, and broken in every
 * way a rule or the schema is meant to catch). The Node port must agree on exit codes, on the diagnostics (rule,
 * file, line, message) and on every generated byte. XSD and lint messages are compared as "file:line" because
 * libxml2's wording is not reproduced.
 */
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('fs');
const path = require('path');
const { MUTATIONS, GOLDEN, build, capture, normalise } = require('./helpers');
const generate = require('../lib/generate');
const check = require('../lib/check');
const lint = require('../lib/lint');
const { buildModel } = require('../lib/registry');

for (const m of MUTATIONS) {
  test(`parity: ${m.name}`, () => {
    const g = GOLDEN.cases[m.name];
    const root = build(m);
    const manifest = path.join(root, 'design/manifest.xml');
    const schema = path.join(root, 'design/schema.xsd');
    const same = (got, want, label) => {
      assert.equal(got.code, want.code, `${label}: exit code`);
      // the Python tools died with a traceback on a malformed registry: the port reports it instead
      if (want.out[0] && want.out[0].startsWith('Traceback'))
        return assert.ok(got.lines.join('\n').includes('malformed XML'), `${label}: says why`);
      return assert.deepEqual(normalise(got.lines, root), want.out, `${label}: output`);
    };

    same(
      capture((out) => check.run({ root, manifest, schema, check: true, out })),
      g.check,
      'check',
    );
    same(
      capture((out) =>
        check.run({
          root,
          manifest,
          check: false,
          verifyCanonical: true,
          outFile: path.join(root, 'design/canonical.index.txt'),
          out,
        }),
      ),
      g.verify,
      'verify',
    );
    same(
      capture((out) => lint.run({ manifest, schema, dir: path.join(root, 'design'), out })),
      g.lint,
      'lint',
    );
    same(
      capture((out) => generate.run({ root, manifest, check: true, out, err: out })),
      g.gen,
      'gen --check',
    );

    const gw = capture((out) => generate.run({ root, manifest, out, err: out }));
    if (g.genwrite.out[0] && g.genwrite.out[0].startsWith('Traceback'))
      assert.ok(gw.lines.join('\n').includes('malformed XML'));
    assert.equal(gw.code, g.genwrite.code, 'gen: exit code');
    if (g.genwrite.files) {
      for (const [f, want] of Object.entries(g.genwrite.files)) {
        // the one deliberate difference: the header names the Node command, not generate.py
        const got = fs
          .readFileSync(path.join(root, 'components/ui/gluestack-ui-provider', f), 'utf8')
          .replace(
            '// Generated by flipova-design gen -- do not edit by hand.',
            '// Generated by design/tools/sources/generate.py -- do not edit by hand.',
          );
        assert.equal(got, want, `gen: ${f} is byte-identical`);
      }
    }

    // canonical index: same document as the recorded one (the recorder printed it to stdout)
    let ctx = null;
    try {
      ctx = buildModel(root, manifest);
    } catch {
      /* malformed registry: the recorded run failed too */
    }
    if (g.canonical.code === 0 && ctx)
      assert.ok(
        g.canonical.text.includes(
          check
            .canonicalDocument(ctx)
            .replace(
              '# generated by flipova-design canonical',
              '# generated by design/tools/sources/checker.py --emit-canonical',
            ),
        ),
        'canonical document',
      );

    // --sync-version
    const sy = capture((out) => check.run({ root, manifest, check: false, syncVersion: true, out }));
    assert.equal(sy.code, g.sync.code, 'sync: exit code');
    for (const [f, head] of Object.entries(g.sync.files)) {
      const text = fs.readFileSync(path.join(root, 'design', f), 'utf8').replace(/<\?.*?\?>|<!--[\s\S]*?-->/g, '');
      assert.equal(/<[A-Za-z][^>]*>/.exec(text)[0], head, `sync: root tag of ${f}`);
    }
    fs.rmSync(root, { recursive: true, force: true });
  });
}
